CREATE DATABASE IF NOT EXISTS campuskart; USE campuskart;
CREATE TABLE IF NOT EXISTS users(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,student_id VARCHAR(30) UNIQUE NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password_hash VARCHAR(64) NOT NULL,department VARCHAR(80) NOT NULL,class_year VARCHAR(20) NOT NULL,division VARCHAR(10) NOT NULL,contact VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT PRIMARY KEY AUTO_INCREMENT,seller_id INT NOT NULL,name VARCHAR(120) NOT NULL,price DECIMAL(10,2) NOT NULL,category VARCHAR(50) NOT NULL,item_condition VARCHAR(30) NOT NULL,item_age VARCHAR(50) NOT NULL,description VARCHAR(1000) NOT NULL,image_data MEDIUMBLOB NOT NULL,image_type VARCHAR(50) NOT NULL,status ENUM('AVAILABLE','SOLD') NOT NULL DEFAULT 'AVAILABLE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,sold_at TIMESTAMP NULL,CONSTRAINT fk_product_seller FOREIGN KEY(seller_id) REFERENCES users(id) ON DELETE CASCADE);